      "text": "I feel this book of scripture is best looked at as a group of songs rather than one flowing song. There will be a lot of jumping back and forth between past and present through these different songs and stories, and I want to do my best to clarify that when we go through it. This book of the Bible is a very interesting one that looks deep into the relationship of the believer and Jesus Christ.",
