      "chapter": 1,
      "verse": 0,
      "startVerse": 0,
      "endVerse": 0,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "Solomon is (of course) the writer (as we will see in a moment), and it is certainly something that is applicable to himself as he will be the shepherd that the Shulamite woman falls in love with. Solomon can do nothing but write about himself, seeing as this is what he was experiencing. The important thing to note and remember through this reading is (whether Solomon understood it or not) this wasn't about him. It was about Christ. All of scripture was/is about Christ.",
