      "text": "Solomon is a widely known figure in religious circles, but there was something that shouldn't be lost on mere religion alone. Solomon knew the God of the Bible. He conversed with God. He desired to lead the people for God. Jerusalem needed a Godly leader, and Solomon was the one chosen for the job. Through all his wisdom, he eventually understands the relationship aspect that God desires, and I believe that God reveals this through this story/song.",
