      "text": "So, as we've mentioned before, Solomon means \"Peace.\" Even more interesting is that Solomon was the king of Jerusalem, which, being interpreted, means, \"The City of Peace.\" It seems there is a lot of peace in this picture here as she desires the peaceful kiss of the one she loves. A kiss may seem like a little thing in our society today, but it meant a great deal through Scripture. David tells us in Psalm 2:12:",
