      "startVerse": 2,
      "endVerse": 2,
      "author": "Psalm 2:12",
      "authorHandle": "",
      "text": "\"Kiss the Son, lest he be angry, and ye perish from the way, when his wrath is kindled but a little. Blessed are all they that put their trust in him.\" Psalm 2:12",
      "likes": 0,
      "isLikedByUser": false,
      "isBookmarkedByUser": false,
