      "startVerse": 2,
      "endVerse": 2,
      "author": "Tried By Fire",
      "authorHandle": "@TriedByFire",
      "text": "There are a lot of addicts in our society today. They are addicted to drinking and are in love with it. They think that kissing their drink will give them fulfillment, but in the end, it just leaves them in pain and more empty than they were before. The only true way to become fulfilled is through the love of Christ.",
