          "book": "Song of Solomon",
          "chapter": 1,
          "verse": 0,
          "startVerse": 0,
          "endVerse": 0,
          "author": "Tried By Fire",
          "authorHandle": "@TriedByFire",
          "text": "There are a plethora of books written and recorded by Solomon that are not even located in scripture. Some are found in books like the Apocrypha, and others are books that have not made their way into scripture (perhaps things like journal entries). Other holy books even talk about Solomon and his glory (including, but not limited to, the Quran).",
          "likes": 0,
