          "text": "Solomon gets this out of the way rather quickly. I don’t think he wants the glory to be focused on himself here, so he just lets it be known that it was Solomon who wrote this song, simply because it was something that meant a lot to him. I imagine that he was inspired by his father, because David was such an avid writer of songs.",
